package com.yeyamo_mobile.api.messaging_service.infrastructure.persistence;
import java.time.Instant;import java.util.UUID;import org.springframework.data.cassandra.core.cql.PrimaryKeyType;import org.springframework.data.cassandra.core.mapping.*;import com.yeyamo_mobile.api.messaging_service.domain.*;
@Table("conversation_members")public class ConversationMemberEntity{@PrimaryKeyColumn(name="conversation_id",type=PrimaryKeyType.PARTITIONED)private UUID conversationId;@PrimaryKeyColumn(name="user_id",type=PrimaryKeyType.CLUSTERED)private String userId;@Column private MemberRole role;@Column private MemberStatus status;@Column("joined_at")private Instant joinedAt;@Column("left_at")private Instant leftAt;@Column("last_read_message_id")private UUID lastReadMessageId;@Column("last_read_at")private Instant lastReadAt;
 public static ConversationMemberEntity active(UUID conversation,String user,MemberRole role){var m=new ConversationMemberEntity();m.conversationId=conversation;m.userId=user;m.role=role;m.status=MemberStatus.ACTIVE;m.joinedAt=Instant.now();return m;}public void leave(MemberStatus status){this.status=status;leftAt=Instant.now();}public void read(UUID message,Instant at){lastReadMessageId=message;lastReadAt=at;}public void promote(MemberRole role){this.role=role;}
 public UUID getConversationId(){return conversationId;}public String getUserId(){return userId;}public MemberRole getRole(){return role;}public MemberStatus getStatus(){return status;}public Instant getJoinedAt(){return joinedAt;}public Instant getLeftAt(){return leftAt;}public UUID getLastReadMessageId(){return lastReadMessageId;}public Instant getLastReadAt(){return lastReadAt;}}
